import { WASH_FIELD_GLSL } from './shaders.js';
// Shader sources shared by the smoke and wash solvers.
const solidGLSL = `uniform vec4 card;uniform sampler2D obstacles;float keySolid(vec2 uv){return step(.5,texture2D(obstacles,uv).r);}float solid(vec2 uv){vec2 q=abs(uv-card.xy)-card.zw;return max(step(max(q.x,q.y),0.),keySolid(uv));}`;

const emissionGLSL = `uniform float pulse,clock,impact;uniform vec4 pourShape,pourFlow;uniform float aspect;uniform vec3 palette[7];uniform bool downwardFlow,preservePigmentRatio;uniform float impulse,swirl,load;${solidGLSL}${WASH_FIELD_GLSL}
 void edge(vec2 uv,out float band,out vec2 normal,out vec3 dye){
 vec2 p=(uv-card.xy)*vec2(aspect,1.);vec2 h=card.zw*vec2(aspect,1.);vec2 q=abs(p)-h;
 float dist=length(max(q,0.))+min(max(q.x,q.y),0.);
 normal=normalize(max(q,0.)*sign(p)+vec2(.00001));
 if(q.x>q.y&&q.x<0.)normal=vec2(sign(p.x),0.);if(q.y>=q.x&&q.y<0.)normal=vec2(0.,sign(p.y));
 float angle=atan(p.y,p.x);float variation=.72+.16*sin(angle*pourFlow.x+pourShape.z+clock*2.)+.12*sin(angle*(pourFlow.x+6.)+pourShape.x-clock*3.);
 band=exp(-pow((dist-.008)/(.012*pourShape.w),2.))*step(0.,dist)*variation*pulse*(1.+impact*3.*exp(-clock*5.));
 float sector=fract((angle+3.14159265)/6.2831853)*7.;int first=int(floor(sector));int second=first==6?0:first+1;dye=mix(palette[first],palette[second],smoothstep(.12,.88,fract(sector)));
 }`;

export function createFluidShaders(vorticity) {
  return {
    emit: `varying vec2 vUv;uniform sampler2D source;uniform bool isVelocity;${emissionGLSL}void main(){float band;vec2 normal;vec3 dye;edge(vUv,band,normal,dye);vec4 old=texture2D(source,vUv);if(isVelocity){vec2 tangent=vec2(-normal.y,normal.x);gl_FragColor=vec4(clamp((old.xy+band*(mix((downwardFlow?vec2(normal.x*.45,min(normal.y,0.)-.75):normal),normal*1.7,impact*exp(-clock*7.))*impulse+tangent*sin(clock*(2.+pourFlow.y)+vUv.y*(20.+pourFlow.z*15.)+pourShape.z)*swirl))*(1.-solid(vUv)),vec2(-45.),vec2(45.)),0.,1.);}else{vec3 added=dye*band*load;vec2 p=(vUv-card.xy)*vec2(aspect,1.);
float broad=wcCloud(p*17.+pourShape.xy);float detail=wcCloud(p*43.+vec2(broad*.9)+pourShape.xy);
float detailMass=old.a+dot(added,vec3(1./3.))*detail;
vec4 ink=vec4(old.rgb+added,detailMass);if(preservePigmentRatio){float peak=max(ink.r,max(ink.g,ink.b));ink*=min(1.,1.4/max(peak,.000001));}else{ink.rgb=min(vec3(1.4),ink.rgb);}gl_FragColor=ink*(1.-solid(vUv));}}`,
    advect: `varying vec2 vUv;uniform sampler2D source,velocityTex;uniform vec2 texel;uniform float delta,fade,diffusion;uniform bool limitPigment,limitVelocity,preservePigmentRatio;${solidGLSL}void main(){vec2 v=texture2D(velocityTex,vUv).xy;vec2 departure=clamp(vUv-v*texel*delta,texel,1.-texel);vec2 travel=departure-vUv;for(int j=1;j<=12;j++){vec2 probe=vUv+travel*(float(j)/12.);if(solid(probe)>.5){departure=vUv+travel*(float(j-1)/12.);break;}}vec4 carried=texture2D(source,departure);vec4 neighbours=(texture2D(source,departure+vec2(texel.x,0.))+texture2D(source,departure-vec2(texel.x,0.))+texture2D(source,departure+vec2(0.,texel.y))+texture2D(source,departure-vec2(0.,texel.y)))*.25;carried=mix(carried,neighbours,diffusion);gl_FragColor=carried*fade;gl_FragColor*=1.-solid(vUv);if(limitPigment){if(preservePigmentRatio){float peak=max(gl_FragColor.r,max(gl_FragColor.g,gl_FragColor.b));gl_FragColor*=min(1.,.82/max(peak,.000001));}else{gl_FragColor.rgb=clamp(gl_FragColor.rgb,0.,.82);}}if(limitVelocity)gl_FragColor=vec4(clamp(gl_FragColor.xy,vec2(-45.),vec2(45.)),0.,1.);}`,
    curlPass: `varying vec2 vUv;uniform sampler2D v;uniform vec2 texel;void main(){float l=texture2D(v,vUv-vec2(texel.x,0.)).y,r=texture2D(v,vUv+vec2(texel.x,0.)).y,b=texture2D(v,vUv-vec2(0.,texel.y)).x,t=texture2D(v,vUv+vec2(0.,texel.y)).x;gl_FragColor=vec4((r-l-t+b)*.5,0.,0.,1.);}`,
    confine: `varying vec2 vUv;uniform sampler2D v,c;uniform vec2 texel;uniform float delta,gravity;void main(){float l=abs(texture2D(c,vUv-vec2(texel.x,0.)).r),r=abs(texture2D(c,vUv+vec2(texel.x,0.)).r),b=abs(texture2D(c,vUv-vec2(0.,texel.y)).r),t=abs(texture2D(c,vUv+vec2(0.,texel.y)).r),center=texture2D(c,vUv).r;vec2 f=vec2(t-b,l-r);f=f/(length(f)+.0001)*center*${Number(vorticity).toFixed(4)};gl_FragColor=vec4(clamp(texture2D(v,vUv).xy+(f+vec2(0.,-gravity))*delta,vec2(-45.),vec2(45.)),0.,1.);}`,
    divergencePass: `varying vec2 vUv;uniform sampler2D v;uniform vec2 texel;${solidGLSL}void main(){float l=texture2D(v,vUv-vec2(texel.x,0.)).x,r=texture2D(v,vUv+vec2(texel.x,0.)).x,b=texture2D(v,vUv-vec2(0.,texel.y)).y,t=texture2D(v,vUv+vec2(0.,texel.y)).y;vec2 center=texture2D(v,vUv).xy;l=mix(l,-center.x,solid(vUv-vec2(texel.x,0.)));r=mix(r,-center.x,solid(vUv+vec2(texel.x,0.)));b=mix(b,-center.y,solid(vUv-vec2(0.,texel.y)));t=mix(t,-center.y,solid(vUv+vec2(0.,texel.y)));gl_FragColor=vec4((r-l+t-b)*.5,0.,0.,1.);}`,
    jacobi: `varying vec2 vUv;uniform sampler2D p,d;uniform vec2 texel;${solidGLSL}void main(){float l=texture2D(p,vUv-vec2(texel.x,0.)).r,r=texture2D(p,vUv+vec2(texel.x,0.)).r,b=texture2D(p,vUv-vec2(0.,texel.y)).r,t=texture2D(p,vUv+vec2(0.,texel.y)).r;float center=texture2D(p,vUv).r;l=mix(l,center,solid(vUv-vec2(texel.x,0.)));r=mix(r,center,solid(vUv+vec2(texel.x,0.)));b=mix(b,center,solid(vUv-vec2(0.,texel.y)));t=mix(t,center,solid(vUv+vec2(0.,texel.y)));gl_FragColor=vec4((l+r+b+t-texture2D(d,vUv).r)*.25,0.,0.,1.);}`,
    project: `varying vec2 vUv;uniform sampler2D v,p;uniform vec2 texel;${solidGLSL}void main(){float l=texture2D(p,vUv-vec2(texel.x,0.)).r,r=texture2D(p,vUv+vec2(texel.x,0.)).r,b=texture2D(p,vUv-vec2(0.,texel.y)).r,t=texture2D(p,vUv+vec2(0.,texel.y)).r;float center=texture2D(p,vUv).r;l=mix(l,center,solid(vUv-vec2(texel.x,0.)));r=mix(r,center,solid(vUv+vec2(texel.x,0.)));b=mix(b,center,solid(vUv-vec2(0.,texel.y)));t=mix(t,center,solid(vUv+vec2(0.,texel.y)));vec2 vel=texture2D(v,vUv).xy-vec2(r-l,t-b)*.5;vel*=1.-solid(vUv);if(solid(vUv+vec2(texel.x,0.))>.5)vel.x=min(vel.x,0.);if(solid(vUv-vec2(texel.x,0.))>.5)vel.x=max(vel.x,0.);if(solid(vUv+vec2(0.,texel.y))>.5)vel.y=min(vel.y,0.);if(solid(vUv-vec2(0.,texel.y))>.5)vel.y=max(vel.y,0.);gl_FragColor=vec4(vel,0.,1.);}`,
  };
}
